query LiteratureTableSearch($from: Int, $size: Int, $predicate: Predicate, $q: String) {
  literatureSearch(predicate: $predicate, q: $q) {
    documents(from: $from, size: $size) {
      from
      size
      total
      results {
        id
        title
        authors {
          firstName
          lastName
        }
        countriesOfCoverage
        countriesOfResearcher
        year
        identifiers {
          doi
        }
        gbifDOIs
        literatureType
        relevance
        source
        topics
        websites
      }
    }
  }
}
